 (w/'summary.json').write_text(json.dumps({'configurations':configs,'mutants_caught':caught,'source_controls':len(controls),'admission':admission},indent=2)+'\n');print('shell lifecycle fixture:',len(configs),'configurations;',len(caught),'mutants;',sum(x['functions']for x in admission),'plans admitted')
